import React from 'react';
import { motion } from 'framer-motion';

/* These come from your actual models/metrics.json — update after retraining */
const MODEL_METRICS = [
  { label: 'MAE',       value: '6.72',  unit: '$/point' },
  { label: 'RMSE',      value: '8.08',  unit: '$/point' },
  { label: 'R² Score',  value: '0.667', unit: 'explained var.' },
  { label: 'Dir. Acc.', value: '54.4%', unit: 'current model' },
  { label: 'Train Set', value: '576',   unit: 'sequences' },
  { label: 'Lookback',  value: '60',    unit: 'days window' },
];

const MetricsCard = () => (
  <motion.div
    className="card metrics-card"
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.45, delay: 0.26 }}
  >
    <div className="card-title">
      <div className="card-ico ico-g">📊</div>
      <span className="card-title-text">Model Metrics</span>
    </div>

    <div className="metrics-grid">
      {MODEL_METRICS.map((m, i) => (
        <div key={i} className="metric-item">
          <div className="metric-label">{m.label}</div>
          <div className="metric-value">{m.value}</div>
          <div className="metric-unit">{m.unit}</div>
        </div>
      ))}
    </div>
  </motion.div>
);

export default MetricsCard;
